local Players=game:GetService("Players") local LocalPlayer=Players.LocalPlayer local RunService=game:GetService("RunService") local CoreGui=game:GetService("CoreGui") local UserInputService=game:GetService("UserInputService") local Workspace=game:GetService("Workspace") local CurrentCamera=Workspace.CurrentCamera local ScreenGui=Instance.new("ScreenGui") ScreenGui.Name="ChakritFixV7Long" ScreenGui.Parent=CoreGui ScreenGui.ResetOnSpawn=false local ToggleBtn=Instance.new("TextButton") ToggleBtn.Size=UDim2.new(0,100,0,45) ToggleBtn.Position=UDim2.new(0,15,0.4,0) ToggleBtn.BackgroundColor3=Color3.fromRGB(15,15,20) ToggleBtn.Text="⚡ CHAKRIT V7" ToggleBtn.TextColor3=Color3.fromRGB(0,255,150) ToggleBtn.Font=Enum.Font.GothamBold ToggleBtn.TextSize=13 ToggleBtn.Parent=ScreenGui local ToggleCorner=Instance.new("UICorner") ToggleCorner.CornerRadius=UDim.new(0,8) ToggleCorner.Parent=ToggleBtn local ToggleStroke=Instance.new("UIStroke") ToggleStroke.Color=Color3.fromRGB(0,255,150) ToggleStroke.Thickness=1.5 ToggleStroke.Parent=ToggleBtn local MainFrame=Instance.new("Frame") MainFrame.Size=UDim2.new(0,340,0,240) MainFrame.Position=UDim2.new(0.5,-170,0.5,-120) MainFrame.BackgroundColor3=Color3.fromRGB(10,10,12) MainFrame.BackgroundTransparency=0.1 MainFrame.Visible=true MainFrame.Parent=ScreenGui local MainCorner=Instance.new("UICorner") MainCorner.CornerRadius=UDim.new(0,15) MainCorner.Parent=MainFrame local UIStroke=Instance.new("UIStroke") UIStroke.Color=Color3.fromRGB(0,255,150) UIStroke.Thickness=2 UIStroke.Parent=MainFrame local Title=Instance.new("TextLabel") Title.Size=UDim2.new(1,0,0,45) Title.Text="CHAKRIT REAL BRING V7" Title.TextColor3=Color3.fromRGB(255,255,255) Title.BackgroundColor3=Color3.fromRGB(0,255,150) Title.BackgroundTransparency=0.7 Title.Font=Enum.Font.GothamBold Title.TextSize=15 Title.Parent=MainFrame local TitleCorner=Instance.new("UICorner") TitleCorner.CornerRadius=UDim.new(0,15) TitleCorner.Parent=Title local BringBtn=Instance.new("TextButton") BringBtn.Size=UDim2.new(0,280,0,60) BringBtn.Position=UDim2.new(0,30,0,75) BringBtn.BackgroundColor3=Color3.fromRGB(255,50,50) BringBtn.Text="ระบบดึงอัตโนมัติทีละคน: ปิด (OFF)" BringBtn.TextColor3=Color3.fromRGB(255,255,255) BringBtn.Font=Enum.Font.GothamBold BringBtn.TextSize=16 BringBtn.Parent=MainFrame local BringCorner=Instance.new("UICorner") BringCorner.CornerRadius=UDim.new(0,8) BringCorner.Parent=BringBtn local Status=Instance.new("TextLabel") Status.Size=UDim2.new(1,0,0,40) Status.Position=UDim2.new(0,0,0,165) Status.BackgroundTransparency=1 Status.Text="สถานะ: รอการเปิดสวิตช์..." Status.TextColor3=Color3.fromRGB(150,150,150) Status.Font=Enum.Font.GothamMedium Status.TextSize=14 Status.Parent=MainFrame ToggleBtn.MouseButton1Click:Connect(function() MainFrame.Visible=not MainFrame.Visible end) local dragging,dragInput,dragStart,startPos MainFrame.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=true dragStart=input.Position startPos=MainFrame.Position end end) MainFrame.InputChanged:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch then dragInput=input end end) UserInputService.InputChanged:Connect(function(input) if input==dragInput and dragging then local delta=input.Position-dragStart MainFrame.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset+delta.X,startPos.Y.Scale,startPos.Y.Offset+delta.Y) end end) UserInputService.InputEnded:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=false end end) local IsHunting=false local HuntConnection=nil local CurrentTarget=nil local function GetNextTarget() for _,player in pairs(Players:GetPlayers()) do if player~=LocalPlayer and player.Character and player.Character:FindFirstChild("Humanoid") then local humanoid=player.Character:FindFirstChild("Humanoid") if humanoid.Health>0 and player.Character:FindFirstChild("HumanoidRootPart") then return player end end end return nil end local function HideCharacter(targetChar) for _,part in pairs(targetChar:GetDescendants()) do if part:IsA("BasePart") or part:IsA("Decal") then if part.Name~="HumanoidRootPart" then part.Transparency=1 end end end end BringBtn.MouseButton1Click:Connect(function() IsHunting=not IsHunting if IsHunting then BringBtn.BackgroundColor3=Color3.fromRGB(0,255,150) BringBtn.Text="ระบบดึงอัตโนมัติทีละคน: เปิด (ON)" BringBtn.TextColor3=Color3.fromRGB(10,10,10) HuntConnection=RunService.Heartbeat:Connect(function() if not IsHunting then return end if not CurrentTarget or not CurrentTarget.Character or not CurrentTarget.Character:FindFirstChild("Humanoid") or CurrentTarget.Character.Humanoid.Health<=0 then CurrentTarget=GetNextTarget() if not CurrentTarget then Status.Text="🎉 เคลียร์ห้องสำเร็จ! ทุกคนตายหมด" Status.TextColor3=Color3.fromRGB(255,215,0) return end end pcall(function() local myChar=LocalPlayer.Character local targetChar=CurrentTarget.Character if myChar and targetChar then local myHRP=myChar:FindFirstChild("HumanoidRootPart") local targetHRP=targetChar:FindFirstChild("HumanoidRootPart") if myHRP and targetHRP then Status.Text="🎯 ล็อกเป้า: "..CurrentTarget.DisplayName.." [HP: "..math.floor(targetChar.Humanoid.Health).."]" Status.TextColor3=Color3.fromRGB(0,255,255) HideCharacter(targetChar) targetHRP.CFrame=myHRP.CFrame * CFrame.new(0,0,-4.5) targetHRP.Velocity=Vector3.new(0,0,0) CurrentCamera.CFrame=CFrame.new(CurrentCamera.CFrame.Position,targetHRP.Position) end end end) end) else IsHunting=false if HuntConnection then HuntConnection:Disconnect() HuntConnection=nil end CurrentTarget=nil BringBtn.BackgroundColor3=Color3.fromRGB(255,50,50) BringBtn.Text="ระบบดึงอัตโนมัติทีละคน: ปิด (OFF)" BringBtn.TextColor3=Color3.fromRGB(255,255,255) Status.Text="หยุดระบบดึงแล้ว" Status.TextColor3=Color3.fromRGB(150,150,150) end end)
